def fill_between_walls(grid, wall, fill=3):
    """Non-wall cells with a wall both above and below in their column, or both left and right in their row, become `fill`."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    for i in range(h):
        for j in range(w):
            if grid[i][j] == wall: continue
            colw = [r for r in range(h) if grid[r][j] == wall]
            roww = [c for c in range(w) if grid[i][c] == wall]
            if (any(r < i for r in colw) and any(r > i for r in colw)) or                (any(c < j for c in roww) and any(c > j for c in roww)):
                out[i][j] = fill
    return out

